#!/bin/sh
V82_DOC_DIR=${V82_DOC_DIR:-$STATE_DIR/generated-docs-v82}
mkdir -p "$V82_DOC_DIR" 2>/dev/null || true
v82_package_api_report(){ ui_text 'Package adapter API' "Manager: $(pkg_api_manager 2>/dev/null || echo unavailable)\n\nUnified operations:\npkg_refresh\npkg_search\npkg_install_packages\npkg_remove_packages\npkg_upgrade_packages\npkg_info\npkg_list_installed\npkg_list_orphans"; }
v82_rootfs_api_report(){ ui_text 'RootFS API' 'Unified operations:\nrootfs_api_mount\nrootfs_api_unmount\nrootfs_api_health\nrootfs_api_snapshot\nrootfs_api_archive\nrootfs_api_diff\nrootfs_api_report'; }
v82_generate_developer_docs(){ out="$V82_DOC_DIR/developer-api-$(date +%Y%m%d-%H%M%S).md"; { echo '# iSH-AOK Developer API'; echo; echo '## Package API'; grep -E '^[a-zA-Z0-9_]+\(\)' "$ISH_AOK_CONFIG_ROOT/lib/package_api_v82.sh"; echo; echo '## RootFS API'; grep -E '^[a-zA-Z0-9_]+\(\)' "$ISH_AOK_CONFIG_ROOT/lib/rootfs_api_v82.sh"; echo; echo '## UI Components'; grep -E '^[a-zA-Z0-9_]+\(\)' "$ISH_AOK_CONFIG_ROOT/lib/ui_components_v82.sh"; echo; echo '## Dynamic modules'; command -v sdk_module_report >/dev/null 2>&1 && sdk_module_report || true; } >"$out"; ui_msg 'Developer documentation' "$out"; }
v82_portability_report(){ out="$V82_DOC_DIR/portability-$(date +%Y%m%d-%H%M%S).txt"; { echo "$PROGRAM $VERSION portability report"; echo "Shell: ${SHELL:-unknown}"; for c in sh awk sed grep find xargs tar mount chroot; do command -v "$c" >/dev/null 2>&1 && echo "OK $c" || echo "MISSING $c"; done; echo; echo 'Non-POSIX constructs:'; grep -R -n -E '\[\[|function[[:space:]]+[A-Za-z_]|<\(' "$ISH_AOK_CONFIG_ROOT"/lib "$ISH_AOK_CONFIG_ROOT"/modules 2>/dev/null || true; } >"$out"; ui_text 'Portability report' "$(cat "$out")"; }
v82_reliability_menu(){ while :; do c=$(ui_menu 'Architecture and Reliability' 'Unified APIs, portability checks, caches, tests and generated documentation.' packages 'Package adapter API' rootfs 'RootFS API' docs 'Generate developer documentation' portability 'Run portability audit' cache 'Clear discovery caches' tests 'Run test suite') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in packages) v82_package_api_report;; rootfs) v82_rootfs_api_report;; docs) v82_generate_developer_docs;; portability) v82_portability_report;; cache) cache_clear; ui_msg Cache 'Caches cleared.';; tests) run_capture 'Project tests' sh -c 'cd "$1" && for t in tests/*.sh; do sh "$t" || exit; done' sh "$ISH_AOK_CONFIG_ROOT";; esac; done; }
